package linearboard

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"clawbridge/internal/bus"
	"clawbridge/internal/linearprovider"
)

// These complete serialized records were generated by the real historical L1
// Service at commit 8aef0f97802169efdf6895eb84bf468a3a9f05c8, retained verbatim
// in the independently generated linear-l1-v3-ledgers fixture. Their literal
// digests/paths catch a payload-version or field-order change in the new client.
func TestLinearV2ReadsHistoricalSerializedL1AcceptedAndPending(t *testing.T) {
	const namespace = "344a2caac7a1e44612b18052cc09852d21f9cbb9f99e4e21772e06a2934e02d2"
	const accepted = `{"version":1,"digest":"483ac34bff17b68a711404cf2a5f0c7c8b8acdf59dbae3fe39ff41b279d039cd","state":"accepted","receipt":{"id":"55555555-5555-4555-8555-555555555555","identifier":"SYN-OLD-1","project_id":"","team_id":"11111111-1111-4111-8111-111111111111"},"updated_at":"2026-10-22T12:00:00Z"}` + "\n"
	const pending = `{"version":1,"digest":"872e5e83cf9d33375246ed5ad4cb8c1d90b7654f3bec5ad035a7f5988266ef7e","state":"pending","updated_at":"2026-10-22T12:00:00Z"}` + "\n"
	for _, state := range []string{"accepted", "pending"} {
		t.Run(state, func(t *testing.T) {
			s, a, _, scope := testV2(t)
			a.old = bus.TaskboardBinding{WorkspaceID: "ws_845da0452eae27818620420ee170d9de", ProjectID: "prj_c3abb00cf1513be99e6420013d2dd070", Configured: true, Revision: 1, UpdatedAt: "2026-10-22T12:09:12.529632000Z", Provider: "linear", LinearTeamIDs: []string{"11111111-1111-4111-8111-111111111111"}, LinearDefaultTeamID: "11111111-1111-4111-8111-111111111111"}
			a.actor = "ses_9d469ac6727a903ee7557ada820cce4f"
			a.b = bus.TaskboardBindingV2{WorkspaceID: a.old.WorkspaceID, ProjectID: a.old.ProjectID, Configured: true, Revision: 1, MappingVersion: 2, UpdatedAt: a.old.UpdatedAt, Provider: "linear", Mode: "team_board", LinearTeamIDs: a.old.LinearTeamIDs, LinearDefaultTeamID: a.old.LinearDefaultTeamID, LinearProjectIDs: []string{}}
			s.cfg.Authority = "synthetic:actual-l1-schema3-ledger-authority"
			s.cfg.ProfileID = "lin_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
			s.cfg.Connections = nil
			scope.Args["instance"] = "legacy-worker-instance"
			in := WriteInputV2{WriteInput: WriteInput{Operation: "create", OperationID: "actual-l1-accepted-v3", Title: ptrV2("Historical accepted synthetic issue")}}
			record, filename := accepted, "94b3009fd91359354f86e809305a59b8cc2d2f98a0d2c45997b31f078a0c2afb.json"
			if state == "pending" {
				record = pending
				filename = "04f9cfe3c0546a54fdc3dc624effdd132d28b9dafba126615a7f2ebb82303f4a.json"
				in.OperationID = "actual-l1-pending-v3"
				in.Title = ptrV2("Historical uncertain synthetic issue")
			}
			dir := filepath.Join(s.cfg.LedgerDirectory, namespace)
			if e := os.MkdirAll(dir, 0700); e != nil {
				t.Fatal(e)
			}
			if e := makePrivate(dir); e != nil {
				t.Fatal(e)
			}
			path := filepath.Join(dir, filename)
			if e := os.WriteFile(path, []byte(record), 0600); e != nil {
				t.Fatal(e)
			}
			if e := makePrivate(path); e != nil {
				t.Fatal(e)
			}
			r, e := s.WriteV2(context.Background(), scope, in)
			if state == "accepted" {
				if e != nil || r == nil {
					t.Fatal("historical accepted retry lost", e)
				}
			} else if e == nil || !strings.Contains(e.Error(), "uncertain") {
				t.Fatal("historical pending retry did not retain uncertainty", e)
			}
			b, e := os.ReadFile(path)
			if e != nil || string(b) != record {
				t.Fatal("historical ledger bytes changed", e)
			}
			in.Assignee = linearprovider.Field[*string]{Present: true, Value: nil}
			if _, e = s.WriteV2(context.Background(), scope, in); e == nil || !strings.Contains(e.Error(), "different scoped payload") {
				t.Fatal("new L2 intent bypassed historical operation ID", e)
			}
		})
	}
}
